import{_ as e,c as o,o as r,ae as d}from"./chunks/framework.Cd-3tpCq.js";const m=JSON.parse('{"title":"Product Customer-Group Prices — Create (GraphQL)","description":"","frontmatter":{"outline":false,"examples":[{"id":"admin-catalog-product-cgp-create","title":"Add a Customer-Group Price","description":"Adds a new tier-price row to a product. A null customerGroupId makes the price apply to every group.","query":"mutation AddCGP($input: createAdminCatalogProductCustomerGroupPriceInput!, $productId: Int!) {\\n  createAdminCatalogProductCustomerGroupPrice(input: $input, productId: $productId) {\\n    adminCatalogProductCustomerGroupPrice {\\n      _id\\n      productId\\n      qty\\n      valueType\\n      value\\n      customerGroupId\\n      customerGroupName\\n    }\\n  }\\n}\\n","variables":"{\\n  \\"productId\\": 1,\\n  \\"input\\": {\\n    \\"qty\\": 5,\\n    \\"valueType\\": \\"fixed\\",\\n    \\"value\\": 90.0,\\n    \\"customerGroupId\\": 2\\n  }\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"createAdminCatalogProductCustomerGroupPrice\\": {\\n      \\"adminCatalogProductCustomerGroupPrice\\": {\\n        \\"_id\\": 12,\\n        \\"productId\\": 1,\\n        \\"qty\\": 5,\\n        \\"valueType\\": \\"fixed\\",\\n        \\"value\\": 90.0,\\n        \\"customerGroupId\\": 2,\\n        \\"customerGroupName\\": \\"Wholesale\\"\\n      }\\n    }\\n  }\\n}\\n"}]},"headers":[],"relativePath":"api/graphql-api/admin/catalog/products/customer-group-prices-create.md","filePath":"api/graphql-api/admin/catalog/products/customer-group-prices-create.md"}'),a={name:"api/graphql-api/admin/catalog/products/customer-group-prices-create.md"};function c(u,t,p,n,i,s){return r(),o("div",null,t[0]||(t[0]=[d('<h1 id="product-customer-group-prices-—-create-graphql" tabindex="-1">Product Customer-Group Prices — Create (GraphQL) <a class="header-anchor" href="#product-customer-group-prices-—-create-graphql" aria-label="Permalink to &quot;Product Customer-Group Prices — Create (GraphQL)&quot;">​</a></h1><p>Adds a new customer-group (tier) price to a product. This is a parent-scoped mutation — pass the product as the <code>productId</code> argument alongside the input. The combination of <code>qty</code> and <code>customerGroupId</code> must be unique for the product. A <code>null</code> <code>customerGroupId</code> makes the price apply to every customer group.</p><p><code>valueType</code> is <code>fixed</code> (a flat price at that quantity) or <code>discount</code> (a discount off the base price).</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>See the <a href="/api/graphql-api/admin/catalog/products/">Products overview</a> for how the catalog product menu fits together.</p></div><p>All admin operations require an admin Bearer token — see <a href="/api/graphql-api/admin/authentication.html">Authentication</a>.</p><h2 id="input" tabindex="-1">Input <a class="header-anchor" href="#input" aria-label="Permalink to &quot;Input&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Notes</th></tr></thead><tbody><tr><td><code>productId</code></td><td><code>Int!</code></td><td>yes</td><td>Argument — parent product.</td></tr><tr><td><code>qty</code></td><td><code>Int!</code></td><td>yes</td><td>Quantity threshold (greater than or equal to 1).</td></tr><tr><td><code>valueType</code></td><td><code>String!</code></td><td>yes</td><td><code>fixed</code> or <code>discount</code>.</td></tr><tr><td><code>value</code></td><td><code>Float!</code></td><td>yes</td><td>Price or discount value.</td></tr><tr><td><code>customerGroupId</code></td><td><code>Int</code></td><td>no</td><td><code>null</code> applies the price to every group.</td></tr></tbody></table>',7)]))}const h=e(a,[["render",c]]);export{m as __pageData,h as default};
